//! Parity tests for dtype detection (`tests/fixtures/detect.json`, generated by
//! `tests/fixtures/gen_detect.py`).

mod common;

use common::{cases, decode_frame, load_fixture};
use meerschaum_kernel::detect;
use meerschaum_kernel::dtypes::Srid;
use serde_json::{Value as J, json};

fn srid_json(s: &Srid) -> J {
    match s {
        Srid::Code(i) => json!(i),
        Srid::Authority(s) => json!(s),
    }
}

/// Known Polars limitation: pandas `datetime64[s, ...]` columns are stored with millisecond
/// precision (Polars has no second unit), so their detected precision differs.
fn known_precision_gap(case_name: &str, col: &str) -> bool {
    case_name == "dt_units" && col == "s_ny"
}

#[test]
fn detect_parity() {
    let fixture = load_fixture("detect");
    let mut failures = Vec::new();
    for case in cases(&fixture) {
        let name = case["name"].as_str().unwrap();
        let df = decode_frame(&case["df"]);
        let results = case["results"].as_object().unwrap();
        for (f, expected) in results {
            let actual: J = match f.as_str() {
                "get_unhashable_cols" => json!(detect::get_unhashable_cols(&df)),
                "get_json_cols" => json!(detect::get_json_cols(&df)),
                "get_numeric_cols" => json!(detect::get_numeric_cols(&df)),
                "get_bool_cols" => json!(detect::get_bool_cols(&df)),
                "get_uuid_cols" => json!(detect::get_uuid_cols(&df)),
                "get_datetime_cols" => json!(detect::get_datetime_cols(&df, true, true).unwrap()),
                "get_datetime_cols_aware" => {
                    json!(detect::get_datetime_cols(&df, true, false).unwrap())
                }
                "get_datetime_cols_naive" => {
                    json!(detect::get_datetime_cols(&df, false, true).unwrap())
                }
                "get_datetime_cols_tz_precision" => {
                    let mut m = serde_json::Map::new();
                    for (col, (tz, p)) in
                        detect::get_datetime_cols_tz_precision(&df, true, true).unwrap()
                    {
                        let p = if known_precision_gap(name, &col) {
                            "second"
                        } else {
                            p.name()
                        };
                        m.insert(col, json!([tz, p]));
                    }
                    J::Object(m)
                }
                "get_datetime_cols_types" => {
                    let mut m = serde_json::Map::new();
                    for (col, t) in detect::get_datetime_cols_types(&df) {
                        let t = if known_precision_gap(name, &col) {
                            t.replacen("[ms", "[s", 1)
                        } else {
                            t
                        };
                        m.insert(col, json!(t));
                    }
                    J::Object(m)
                }
                "get_date_cols" => json!(detect::get_date_cols(&df)),
                "get_bytes_cols" => json!(detect::get_bytes_cols(&df)),
                "get_geometry_cols" => json!(detect::get_geometry_cols(&df)),
                "get_geometry_cols_types_srids" => {
                    let mut m = serde_json::Map::new();
                    for (col, (t, srid)) in detect::get_geometry_cols_types_srids(&df) {
                        m.insert(col, json!([t, srid_json(&srid)]));
                    }
                    J::Object(m)
                }
                "get_geometry_cols_types" => json!(detect::get_geometry_cols_types(&df)),
                "get_special_cols" => {
                    let mut m = serde_json::Map::new();
                    for (col, t) in detect::get_special_cols(&df) {
                        let t = if known_precision_gap(name, &col) {
                            t.replacen("[ms", "[s", 1)
                        } else {
                            t
                        };
                        m.insert(col, json!(t));
                    }
                    J::Object(m)
                }
                other => panic!("unhandled {other}"),
            };
            let expected = expected.get("ok").cloned().unwrap_or(J::Null);
            // Compare dicts with key order (Python dict order is observable).
            let same = serde_json::to_string(&expected).unwrap()
                == serde_json::to_string(&actual).unwrap();
            if !same {
                failures.push(format!("{name}.{f}: expected {expected}, got {actual}"));
            }
        }
    }
    if !failures.is_empty() {
        panic!(
            "{} detect parity failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
